func (l *OutputLogger) flushLoop() {
    defer close(l.flushDone)
    ticker := time.NewTicker(logFlushInterval)
    defer ticker.Stop()
    for {
        select {
        case <-l.flushCh:
            return
        case <-ticker.C:
            l.mu.Lock()
            if l.bw != nil {
                _ = l.bw.Flush()
            }
            l.mu.Unlock()
        }
    }
}

